CREATE TABLE IF NOT EXISTS deploy_versions (school_id TEXT NOT NULL,id TEXT NOT NULL,name TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 0,metadata TEXT NOT NULL,created_at INTEGER NOT NULL,deleted INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(school_id,id));
CREATE TABLE IF NOT EXISTS deploy_rows (school_id TEXT NOT NULL,version_id TEXT NOT NULL,scope TEXT NOT NULL,row_id TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,value TEXT NOT NULL,PRIMARY KEY(school_id,version_id,scope,row_id));
CREATE TABLE IF NOT EXISTS deploy_leases (school_id TEXT NOT NULL,version_id TEXT NOT NULL,scope TEXT NOT NULL,holder TEXT NOT NULL,client_id TEXT NOT NULL,fence INTEGER NOT NULL,expires_at INTEGER NOT NULL,PRIMARY KEY(school_id,version_id,scope));
CREATE TABLE IF NOT EXISTS deploy_previews (school_id TEXT NOT NULL,id TEXT NOT NULL,actor_id TEXT NOT NULL,version_id TEXT NOT NULL,base_revision INTEGER NOT NULL,scope TEXT NOT NULL,digest TEXT NOT NULL,workbook TEXT NOT NULL,expires_at INTEGER NOT NULL,PRIMARY KEY(school_id,id));
CREATE TABLE IF NOT EXISTS deploy_publications (school_id TEXT NOT NULL,id TEXT NOT NULL,sequence INTEGER NOT NULL,version_id TEXT NOT NULL,working_revision INTEGER NOT NULL,operation_id TEXT NOT NULL,payload_digest TEXT NOT NULL,payload_key TEXT NOT NULL,envelope TEXT NOT NULL,published_at INTEGER NOT NULL,decision_id TEXT NOT NULL,PRIMARY KEY(school_id,id),UNIQUE(school_id,sequence),UNIQUE(school_id,operation_id));
CREATE TABLE IF NOT EXISTS deploy_pointer (school_id TEXT PRIMARY KEY,sequence INTEGER NOT NULL,publication_id TEXT NOT NULL,revision TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS deploy_deliveries (school_id TEXT NOT NULL,publication_id TEXT NOT NULL,recipient TEXT NOT NULL,state TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,acknowledgement TEXT,PRIMARY KEY(school_id,publication_id,recipient));
CREATE TABLE IF NOT EXISTS deploy_notices (school_id TEXT NOT NULL,version_id TEXT NOT NULL,id TEXT NOT NULL,actor_id TEXT,body TEXT NOT NULL,acknowledged_at INTEGER,PRIMARY KEY(school_id,version_id,id));
CREATE INDEX IF NOT EXISTS deploy_rows_scope ON deploy_rows(school_id,version_id,scope);
CREATE INDEX IF NOT EXISTS deploy_history ON deploy_publications(school_id,version_id,sequence);
CREATE TABLE IF NOT EXISTS deploy_prepared_publications (school_id TEXT NOT NULL,operation_id TEXT NOT NULL,fence INTEGER NOT NULL,payload_digest TEXT NOT NULL,payload_key TEXT NOT NULL,envelope TEXT NOT NULL,document TEXT NOT NULL,dependencies TEXT NOT NULL,contacts_evidence TEXT NOT NULL,publication_id TEXT NOT NULL,sequence INTEGER NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(school_id,operation_id));
CREATE TABLE IF NOT EXISTS deploy_exports(school_id TEXT NOT NULL,publication_id TEXT NOT NULL,file_id TEXT NOT NULL,content_digest TEXT NOT NULL,state TEXT NOT NULL,updated_at INTEGER NOT NULL,last_error TEXT,PRIMARY KEY(school_id,publication_id),UNIQUE(school_id,file_id));

CREATE TABLE IF NOT EXISTS deploy_audit_display(school_id TEXT NOT NULL,actor_id TEXT NOT NULL,hidden_before INTEGER NOT NULL,PRIMARY KEY(school_id,actor_id));
CREATE TABLE IF NOT EXISTS deploy_venue_recovery(school_id TEXT NOT NULL,operation_id TEXT NOT NULL,resolved_at INTEGER NOT NULL,PRIMARY KEY(school_id,operation_id));
